-- V1__schema.sql
-- ShiftCircle schema from docs/06-data-model.md (PostgreSQL 17).
--
-- Conventions: uuid keys generated by the app (a default is provided for seeds and tests), instants
-- are timestamptz in UTC, business dates are America/Regina local dates, editable rows carry
-- "version" for optimistic locking.
--
-- Integrity that must not depend on application code lives here: no double-booking, no overlapping
-- pay periods, a locked pay period refuses time-entry changes, the audit log is append-only, and a
-- rule version can never be approved by the person who created it.

CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ---------------------------------------------------------------------------------------------
-- Facility and people (docs/06 §3.1)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE unit (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code        text NOT NULL UNIQUE,
    name        text NOT NULL,
    kind        text NOT NULL CHECK (kind IN ('LIVING', 'ADMISSIONS', 'CONTROL', 'ESCORT', 'OTHER')),
    -- Rule S-03: 12- and 16-hour patterns need a local agreement on the unit.
    allows_12h  boolean NOT NULL DEFAULT false,
    allows_16h  boolean NOT NULL DEFAULT false,
    active      boolean NOT NULL DEFAULT true,
    version     integer NOT NULL DEFAULT 0
);

CREATE TABLE qualification (
    id   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code text NOT NULL UNIQUE,
    name text NOT NULL
);

CREATE TABLE unit_requirement (
    id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    unit_id                uuid NOT NULL REFERENCES unit (id),
    block                  text NOT NULL CHECK (block IN ('DAY', 'EVENING', 'NIGHT')),
    min_staff              integer NOT NULL CHECK (min_staff > 0),
    qualification_id       uuid REFERENCES qualification (id),
    min_with_qualification integer NOT NULL DEFAULT 0
        CHECK (min_with_qualification >= 0 AND min_with_qualification <= min_staff),
    effective_from         date NOT NULL,
    effective_to           date,
    version                integer NOT NULL DEFAULT 0,
    UNIQUE (unit_id, block, effective_from),
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

CREATE TABLE rotation_pattern (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code        text NOT NULL UNIQUE,
    name        text NOT NULL,
    cycle_days  integer NOT NULL CHECK (cycle_days > 0),
    pattern     jsonb NOT NULL,
    anchor_date date NOT NULL,
    version     integer NOT NULL DEFAULT 0
);

CREATE TABLE employee (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    employee_no         text NOT NULL UNIQUE,
    first_name          text NOT NULL,
    last_name           text NOT NULL,
    classification      text NOT NULL DEFAULT 'CO',
    home_unit_id        uuid REFERENCES unit (id),
    rotation_pattern_id uuid REFERENCES rotation_pattern (id),
    fte                 numeric(3, 2) NOT NULL DEFAULT 1.00 CHECK (fte > 0 AND fte <= 1),
    seniority_date      date NOT NULL,
    active              boolean NOT NULL DEFAULT true,
    is_synthetic        boolean NOT NULL DEFAULT true,
    version             integer NOT NULL DEFAULT 0
);

CREATE TABLE employee_qualification (
    employee_id      uuid NOT NULL REFERENCES employee (id),
    qualification_id uuid NOT NULL REFERENCES qualification (id),
    valid_from       date NOT NULL,
    valid_to         date,
    PRIMARY KEY (employee_id, qualification_id),
    CHECK (valid_to IS NULL OR valid_to >= valid_from)
);

-- ---------------------------------------------------------------------------------------------
-- Rules engine (docs/06 §3.4) — before shift_template, which references the published version
-- ---------------------------------------------------------------------------------------------

CREATE TABLE rule_table (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code          text NOT NULL UNIQUE
        CHECK (code IN ('REST', 'MAX_HOURS', 'CONSECUTIVE', 'LONG_SHIFTS', 'DAYS_OFF', 'PAY',
                        'OT_RANKING', 'SHIFT_LENGTHS')),
    name          text NOT NULL,
    -- Points at the Drools template in the code (docs/04 §5).
    template_ref  text NOT NULL,
    column_schema jsonb NOT NULL
);

CREATE TABLE rule_set_version (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    version          integer NOT NULL UNIQUE CHECK (version > 0),
    status           text NOT NULL
        CHECK (status IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'PUBLISHED', 'SUPERSEDED', 'REJECTED')),
    based_on_version integer,
    effective_from   date NOT NULL,
    change_reason    text,
    created_by       uuid,
    submitted_at     timestamptz,
    approved_by      uuid,
    approved_at      timestamptz,
    published_at     timestamptz,
    build_report     jsonb,
    dry_run_report   jsonb,
    drl_sha256       text,
    -- Maker/checker: one person can never both create and approve a version (T10).
    CONSTRAINT rule_set_version_maker_checker
        CHECK (approved_by IS NULL OR created_by IS NULL OR approved_by <> created_by)
);

-- Only one published version per effective date (docs/06 §3.4).
CREATE UNIQUE INDEX ux_rule_set_version_published_effective
    ON rule_set_version (effective_from)
    WHERE status = 'PUBLISHED';

CREATE TABLE rule_row (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    rule_set_version_id uuid NOT NULL REFERENCES rule_set_version (id),
    rule_table_id       uuid NOT NULL REFERENCES rule_table (id),
    code                text NOT NULL,
    enabled             boolean NOT NULL DEFAULT true,
    params              jsonb NOT NULL DEFAULT '{}'::jsonb,
    severity            text NOT NULL CHECK (severity IN ('BLOCK', 'WARN', 'INFO')),
    override_policy     text NOT NULL CHECK (override_policy IN ('EMERGENCY', 'ACKNOWLEDGE', 'NONE')),
    message             text NOT NULL,
    source              text NOT NULL,
    is_placeholder      boolean NOT NULL DEFAULT false,
    sort_order          integer NOT NULL DEFAULT 0,
    version             integer NOT NULL DEFAULT 0,
    UNIQUE (rule_set_version_id, code)
);

CREATE TABLE rule_check (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    change_type         text NOT NULL,
    payload             jsonb NOT NULL,
    rule_set_version_id uuid NOT NULL REFERENCES rule_set_version (id),
    outcome             text NOT NULL CHECK (outcome IN ('PASS', 'WARN', 'BLOCK')),
    requested_by        uuid,
    created_at          timestamptz NOT NULL DEFAULT now(),
    -- Previews are not stored; every saved change is (docs/06 §3.4).
    saved               boolean NOT NULL DEFAULT false
);

CREATE TABLE rule_result (
    id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    rule_check_id          uuid NOT NULL REFERENCES rule_check (id) ON DELETE CASCADE,
    rule_code              text NOT NULL,
    outcome                text NOT NULL CHECK (outcome IN ('WARN', 'BLOCK', 'INFO')),
    message                text NOT NULL,
    facts                  jsonb NOT NULL DEFAULT '{}'::jsonb,
    evidence_assignment_ids uuid[] NOT NULL DEFAULT '{}'
);

-- ---------------------------------------------------------------------------------------------
-- Scheduling (docs/06 §3.2)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE shift_template (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    code                text NOT NULL UNIQUE,
    label               text NOT NULL,
    start_time          time NOT NULL,
    duration_minutes    integer NOT NULL CHECK (duration_minutes IN (480, 720, 960)),
    regular_allowed     boolean NOT NULL DEFAULT true,
    chip_style          text NOT NULL DEFAULT 'day',
    active              boolean NOT NULL DEFAULT true,
    effective_from      date NOT NULL,
    effective_to        date,
    rule_set_version_id uuid REFERENCES rule_set_version (id),
    version             integer NOT NULL DEFAULT 0,
    CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

CREATE TABLE schedule_period (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    unit_id      uuid NOT NULL REFERENCES unit (id),
    start_date   date NOT NULL,
    end_date     date NOT NULL,
    status       text NOT NULL CHECK (status IN ('DRAFT', 'PUBLISHED')),
    published_at timestamptz,
    published_by uuid,
    version      integer NOT NULL DEFAULT 0,
    CHECK (end_date >= start_date)
);

CREATE TABLE override (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    -- A reason is mandatory and must say something (min 10 characters, docs/07).
    reason              text NOT NULL CHECK (length(btrim(reason)) >= 10),
    rule_codes          text[] NOT NULL DEFAULT '{}',
    rule_set_version_id uuid NOT NULL REFERENCES rule_set_version (id),
    created_by          uuid,
    created_at          timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE shift_assignment (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    employee_id         uuid NOT NULL REFERENCES employee (id),
    unit_id             uuid NOT NULL REFERENCES unit (id),
    shift_template_id   uuid NOT NULL REFERENCES shift_template (id),
    schedule_period_id  uuid REFERENCES schedule_period (id),
    start_at            timestamptz NOT NULL,
    end_at              timestamptz NOT NULL,
    work_date           date NOT NULL,
    kind                text NOT NULL CHECK (kind IN ('ROSTERED', 'EXTRA')),
    source              text NOT NULL CHECK (source IN ('ROTATION', 'MANUAL', 'OVERTIME_OFFER', 'PROPOSAL')),
    status              text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED', 'CANCELLED')),
    override_id         uuid REFERENCES override (id),
    created_by          uuid,
    created_at          timestamptz NOT NULL DEFAULT now(),
    version             integer NOT NULL DEFAULT 0,
    CHECK (end_at > start_at),
    -- No double-booking: one employee cannot be on two live shifts at the same time.
    CONSTRAINT no_overlapping_shifts EXCLUDE USING gist (
        employee_id WITH =,
        tstzrange(start_at, end_at, '[)') WITH &&
    ) WHERE (status <> 'CANCELLED')
);

CREATE TABLE absence (
    id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    employee_id        uuid NOT NULL REFERENCES employee (id),
    shift_assignment_id uuid REFERENCES shift_assignment (id),
    -- Type only. Never a medical reason or free text (FOIP data minimisation).
    type               text NOT NULL CHECK (type IN ('SICK', 'VACATION', 'OTHER')),
    start_at           timestamptz NOT NULL,
    end_at             timestamptz NOT NULL,
    recorded_by        uuid,
    recorded_at        timestamptz NOT NULL DEFAULT now(),
    CHECK (end_at > start_at)
);

CREATE TABLE open_shift (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    unit_id             uuid NOT NULL REFERENCES unit (id),
    shift_template_id   uuid NOT NULL REFERENCES shift_template (id),
    start_at            timestamptz NOT NULL,
    end_at              timestamptz NOT NULL,
    reason              text NOT NULL CHECK (reason IN ('SICK_CALL', 'VACATION', 'EXTRA_COVERAGE', 'OTHER')),
    status              text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'OFFERED', 'FILLED', 'CANCELLED')),
    filled_assignment_id uuid REFERENCES shift_assignment (id),
    created_by          uuid,
    created_at          timestamptz NOT NULL DEFAULT now(),
    version             integer NOT NULL DEFAULT 0,
    CHECK (end_at > start_at)
);

CREATE TABLE overtime_offer (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    open_shift_id uuid NOT NULL REFERENCES open_shift (id),
    employee_id   uuid NOT NULL REFERENCES employee (id),
    rank          integer,
    ordered       boolean NOT NULL DEFAULT false,
    status        text NOT NULL DEFAULT 'OFFERED'
        CHECK (status IN ('OFFERED', 'ACCEPTED', 'DECLINED', 'WITHDRAWN', 'EXPIRED')),
    -- Eligibility at offer time, kept for audit (docs/06 §3.2).
    rule_snapshot jsonb,
    offered_by    uuid,
    offered_at    timestamptz NOT NULL DEFAULT now(),
    responded_at  timestamptz,
    version       integer NOT NULL DEFAULT 0,
    UNIQUE (open_shift_id, employee_id)
);

CREATE TABLE proposal (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    employee_id  uuid NOT NULL REFERENCES employee (id),
    note         text,
    status       text NOT NULL DEFAULT 'SUBMITTED'
        CHECK (status IN ('SUBMITTED', 'ACCEPTED', 'PARTIAL', 'DECLINED')),
    submitted_at timestamptz NOT NULL DEFAULT now(),
    decided_by   uuid,
    decided_at   timestamptz,
    version      integer NOT NULL DEFAULT 0
);

CREATE TABLE proposal_item (
    id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    proposal_id          uuid NOT NULL REFERENCES proposal (id) ON DELETE CASCADE,
    action               text NOT NULL CHECK (action IN ('ADD', 'REMOVE', 'CHANGE')),
    target_assignment_id uuid REFERENCES shift_assignment (id),
    shift_template_id    uuid REFERENCES shift_template (id),
    unit_id              uuid REFERENCES unit (id),
    start_at             timestamptz,
    end_at               timestamptz,
    decision             text NOT NULL DEFAULT 'PENDING'
        CHECK (decision IN ('PENDING', 'ACCEPTED', 'DECLINED')),
    rule_snapshot        jsonb,
    CHECK (end_at IS NULL OR start_at IS NULL OR end_at > start_at)
);

-- ---------------------------------------------------------------------------------------------
-- Time and payroll handoff (docs/06 §3.3)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE pay_period (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    start_date    date NOT NULL,
    end_date      date NOT NULL,
    status        text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'LOCKED')),
    locked_at     timestamptz,
    locked_by     uuid,
    unlock_reason text,
    version       integer NOT NULL DEFAULT 0,
    CHECK (end_date > start_date),
    -- Unlocking a period that was locked requires a reason (docs/09 §2).
    CHECK (status = 'LOCKED' OR locked_at IS NULL OR unlock_reason IS NOT NULL),
    -- Pay periods never overlap.
    CONSTRAINT pay_period_no_overlap EXCLUDE USING gist (
        daterange(start_date, end_date, '[]') WITH &&
    )
);

CREATE TABLE time_entry (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    employee_id         uuid NOT NULL REFERENCES employee (id),
    pay_period_id       uuid NOT NULL REFERENCES pay_period (id),
    shift_assignment_id uuid REFERENCES shift_assignment (id),
    work_date           date NOT NULL,
    start_at            timestamptz NOT NULL,
    end_at              timestamptz NOT NULL,
    hours               numeric(5, 2) NOT NULL CHECK (hours >= 0),
    entry_type          text NOT NULL CHECK (entry_type IN ('SCHEDULED', 'ACTUAL')),
    absence_type        text CHECK (absence_type IN ('SICK', 'VACATION', 'OTHER')),
    pay_code            text CHECK (pay_code IN ('REG', 'OT15', 'OT20', 'SICK', 'VAC', 'STAT')),
    rule_set_version_id uuid REFERENCES rule_set_version (id),
    recorded_by         uuid,
    created_at          timestamptz NOT NULL DEFAULT now(),
    CHECK (end_at > start_at)
);

CREATE TABLE payroll_export (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    pay_period_id uuid NOT NULL REFERENCES pay_period (id),
    generated_at  timestamptz NOT NULL DEFAULT now(),
    generated_by  uuid,
    row_count     integer NOT NULL CHECK (row_count >= 0),
    file_sha256   text NOT NULL
);

-- ---------------------------------------------------------------------------------------------
-- Users and audit (docs/06 §3.5)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE app_user (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    username     text NOT NULL UNIQUE,
    display_name text NOT NULL,
    employee_id  uuid REFERENCES employee (id),
    active       boolean NOT NULL DEFAULT true,
    version      integer NOT NULL DEFAULT 0
);

CREATE TABLE app_user_role (
    user_id uuid NOT NULL REFERENCES app_user (id),
    role    text NOT NULL
        CHECK (role IN ('EMPLOYEE', 'SUPERVISOR', 'RULES_ADMIN', 'RULES_APPROVER', 'AUDITOR', 'DISPLAY')),
    PRIMARY KEY (user_id, role)
);

CREATE TABLE user_unit_scope (
    user_id uuid NOT NULL REFERENCES app_user (id),
    unit_id uuid NOT NULL REFERENCES unit (id),
    PRIMARY KEY (user_id, unit_id)
);

CREATE TABLE audit_event (
    id                  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    occurred_at         timestamptz NOT NULL DEFAULT now(),
    actor_user_id       uuid,
    action              text NOT NULL,
    entity_type         text NOT NULL,
    entity_id           uuid,
    before              jsonb,
    after               jsonb,
    rule_set_version_id uuid,
    override_id         uuid,
    correlation_id      text
);

-- ---------------------------------------------------------------------------------------------
-- Indexes beyond primary and unique keys (docs/06 §4)
-- ---------------------------------------------------------------------------------------------

CREATE INDEX ix_shift_assignment_employee_start ON shift_assignment (employee_id, start_at);
CREATE INDEX ix_shift_assignment_unit_start ON shift_assignment (unit_id, start_at);
CREATE INDEX ix_time_entry_period_employee ON time_entry (pay_period_id, employee_id);
CREATE INDEX ix_overtime_offer_employee_status ON overtime_offer (employee_id, status);
CREATE INDEX ix_audit_event_entity ON audit_event (entity_type, entity_id);
CREATE INDEX ix_audit_event_occurred ON audit_event (occurred_at);
CREATE INDEX ix_rule_row_version_table_order ON rule_row (rule_set_version_id, rule_table_id, sort_order);

-- ---------------------------------------------------------------------------------------------
-- Triggers: append-only audit, locked pay periods
-- ---------------------------------------------------------------------------------------------

-- The audit log can be written and read, never changed or removed. A pilot would also grant the
-- application role INSERT, SELECT only; the trigger is what the prototype can prove.
CREATE OR REPLACE FUNCTION audit_event_is_append_only() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    RAISE EXCEPTION 'audit_event is append-only: % is not allowed', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER audit_event_no_update
    BEFORE UPDATE OR DELETE ON audit_event
    FOR EACH ROW EXECUTE FUNCTION audit_event_is_append_only();

CREATE TRIGGER audit_event_no_truncate
    BEFORE TRUNCATE ON audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION audit_event_is_append_only();

-- A locked pay period freezes its time entries: no insert, update or delete (T11).
CREATE OR REPLACE FUNCTION reject_time_entry_in_locked_period() RETURNS trigger
    LANGUAGE plpgsql AS
$$
DECLARE
    target_period uuid;
    period_status text;
BEGIN
    target_period := COALESCE(NEW.pay_period_id, OLD.pay_period_id);
    SELECT status INTO period_status FROM pay_period WHERE id = target_period;

    IF period_status = 'LOCKED' THEN
        RAISE EXCEPTION 'pay period % is locked; time entries cannot be changed or removed', target_period
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE TRIGGER time_entry_locked_period
    BEFORE INSERT OR UPDATE OR DELETE ON time_entry
    FOR EACH ROW EXECUTE FUNCTION reject_time_entry_in_locked_period();

-- ---------------------------------------------------------------------------------------------
-- Actor references, added last because app_user is created after the tables it acts on.
-- Actor columns are intentionally not enforced by some deployments' seed scripts; the FK keeps
-- audit rows pointing at real users.
-- ---------------------------------------------------------------------------------------------

ALTER TABLE shift_assignment ADD CONSTRAINT fk_shift_assignment_created_by
    FOREIGN KEY (created_by) REFERENCES app_user (id);
ALTER TABLE schedule_period ADD CONSTRAINT fk_schedule_period_published_by
    FOREIGN KEY (published_by) REFERENCES app_user (id);
ALTER TABLE override ADD CONSTRAINT fk_override_created_by
    FOREIGN KEY (created_by) REFERENCES app_user (id);
ALTER TABLE absence ADD CONSTRAINT fk_absence_recorded_by
    FOREIGN KEY (recorded_by) REFERENCES app_user (id);
ALTER TABLE open_shift ADD CONSTRAINT fk_open_shift_created_by
    FOREIGN KEY (created_by) REFERENCES app_user (id);
ALTER TABLE overtime_offer ADD CONSTRAINT fk_overtime_offer_offered_by
    FOREIGN KEY (offered_by) REFERENCES app_user (id);
ALTER TABLE proposal ADD CONSTRAINT fk_proposal_decided_by
    FOREIGN KEY (decided_by) REFERENCES app_user (id);
ALTER TABLE time_entry ADD CONSTRAINT fk_time_entry_recorded_by
    FOREIGN KEY (recorded_by) REFERENCES app_user (id);
ALTER TABLE payroll_export ADD CONSTRAINT fk_payroll_export_generated_by
    FOREIGN KEY (generated_by) REFERENCES app_user (id);
ALTER TABLE rule_set_version ADD CONSTRAINT fk_rule_set_version_created_by
    FOREIGN KEY (created_by) REFERENCES app_user (id);
ALTER TABLE rule_set_version ADD CONSTRAINT fk_rule_set_version_approved_by
    FOREIGN KEY (approved_by) REFERENCES app_user (id);
ALTER TABLE rule_check ADD CONSTRAINT fk_rule_check_requested_by
    FOREIGN KEY (requested_by) REFERENCES app_user (id);
ALTER TABLE pay_period ADD CONSTRAINT fk_pay_period_locked_by
    FOREIGN KEY (locked_by) REFERENCES app_user (id);
ALTER TABLE audit_event ADD CONSTRAINT fk_audit_event_actor
    FOREIGN KEY (actor_user_id) REFERENCES app_user (id);
